-- Depósito: sections and items of a game, kept apart from games.state
-- (see docs/plans/DEPOSITO.md).
--
-- Like the archive, members write here directly: the client runs the same pure
-- rules (src/systems/Depot.ts) and RLS keeps each character's private area
-- (owner_id) away from the other players, in reads, writes and realtime alike.
-- owner_id null is the group's shared depot.

-- ---------------------------------------------------------------- tables

create table public.depot_sections (
  game_id uuid not null references public.games (id) on delete cascade,
  -- Generated by the client (newId), like every record created in game.
  id text not null check (id ~ '^[a-z0-9_-]{1,64}$'),
  name text not null check (char_length(btrim(name)) between 1 and 120),
  icon text check (char_length(icon) <= 16),
  -- null: the group's depot; a character id: that character's private area.
  owner_id text check (char_length(owner_id) between 1 and 64),
  position integer not null default 0,
  -- A character id, or 'mestre'.
  author_id text not null check (char_length(author_id) between 1 and 64),
  -- In the trash since; null while in use.
  deleted_at timestamptz,
  primary key (game_id, id)
);

create table public.depot_items (
  game_id uuid not null,
  id text not null check (id ~ '^[a-z0-9_-]{1,64}$'),
  section_id text not null,
  -- Copy of the section's owner_id, so RLS reads it from the row itself
  -- (kept equal by depot_item_owner_matches below).
  owner_id text check (char_length(owner_id) between 1 and 64),
  name text not null check (char_length(btrim(name)) between 1 and 120),
  kind text not null check (kind in ('equipamento', 'pocao', 'outro')),
  quantity integer not null check (quantity between 1 and 99999),
  notes text not null default '' check (char_length(notes) <= 2000),
  position integer not null default 0,
  author_id text not null check (char_length(author_id) between 1 and 64),
  edited_by text check (char_length(edited_by) between 1 and 64),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  primary key (game_id, id),
  -- Emptying the trash removes a section with the items still in it.
  foreign key (game_id, section_id) references public.depot_sections (game_id, id) on delete cascade
);

create index depot_items_by_section on public.depot_items (game_id, section_id);

-- ---------------------------------------------------------------- RLS

-- The character the current user plays in the game; null for the master and strangers.
create function public.my_character(target_game uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select p.character_id from public.players p
  where p.game_id = target_game and p.user_id = (select auth.uid());
$$;

-- The group's depot is every member's; a private area only its owner's and the master's.
create function public.can_see_depot(target_game uuid, area_owner text)
returns boolean
language sql
stable
set search_path = ''
as $$
  select public.is_member(target_game)
     and (
       area_owner is null
       or public.is_master(target_game)
       or area_owner = public.my_character(target_game)
     );
$$;

revoke execute on function public.my_character(uuid), public.can_see_depot(uuid, text)
  from public, anon;
grant execute on function public.my_character(uuid), public.can_see_depot(uuid, text)
  to authenticated;

alter table public.depot_sections enable row level security;
alter table public.depot_items enable row level security;

create policy "members read the sections they may see" on public.depot_sections
  for select to authenticated using (public.can_see_depot(game_id, owner_id));
-- The check runs on the new row: a player opens sections only in the group's depot or their own area.
create policy "members add sections they may see" on public.depot_sections
  for insert to authenticated with check (public.can_see_depot(game_id, owner_id));
create policy "members edit sections they may see" on public.depot_sections
  for update to authenticated
  using (public.can_see_depot(game_id, owner_id))
  with check (public.can_see_depot(game_id, owner_id));
-- Removing is moving to the trash (an update); only emptying the trash deletes.
create policy "masters empty the trash of sections" on public.depot_sections
  for delete to authenticated using (public.is_master(game_id));

create policy "members read the items they may see" on public.depot_items
  for select to authenticated using (public.can_see_depot(game_id, owner_id));
create policy "members add items they may see" on public.depot_items
  for insert to authenticated with check (public.can_see_depot(game_id, owner_id));
create policy "members edit items they may see" on public.depot_items
  for update to authenticated
  using (public.can_see_depot(game_id, owner_id))
  with check (public.can_see_depot(game_id, owner_id));
create policy "masters empty the trash of items" on public.depot_items
  for delete to authenticated using (public.is_master(game_id));

revoke all on public.depot_sections, public.depot_items from anon;
grant select, insert, update, delete on public.depot_sections, public.depot_items to authenticated;

-- ---------------------------------------------------------------- rules RLS cannot see

-- A section never changes area: its items' owner_id copies would go stale.
create function public.depot_section_keeps_owner()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.owner_id is distinct from old.owner_id then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

revoke execute on function public.depot_section_keeps_owner() from public, anon, authenticated;

create trigger depot_sections_keep_owner
  before update of owner_id on public.depot_sections
  for each row execute function public.depot_section_keeps_owner();

-- An item's owner_id is its section's. security definer: the section may sit in
-- an area the writer cannot see, and the refusal must not tell whose it is.
create function public.depot_item_owner_matches()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.depot_sections s
    where s.game_id = new.game_id and s.id = new.section_id
      and s.owner_id is not distinct from new.owner_id
  ) then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;
  return new;
end;
$$;

revoke execute on function public.depot_item_owner_matches() from public, anon, authenticated;

create trigger depot_items_owner_matches
  before insert or update of section_id, owner_id on public.depot_items
  for each row execute function public.depot_item_owner_matches();

-- A section goes to the trash only when empty. The message is the client's error code.
create function public.depot_section_must_be_empty()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.deleted_at is not null and old.deleted_at is null and exists (
    select 1 from public.depot_items i
    where i.game_id = new.game_id and i.section_id = new.id and i.deleted_at is null
  ) then
    raise exception 'category_not_empty' using errcode = 'check_violation';
  end if;
  return new;
end;
$$;

revoke execute on function public.depot_section_must_be_empty() from public, anon, authenticated;

create trigger depot_sections_trash_only_empty
  before update of deleted_at on public.depot_sections
  for each row execute function public.depot_section_must_be_empty();

-- Importing a save: the whole depot at once. Runs as the caller (RLS applies).
create function public.replace_depot(target_game uuid, sections jsonb, items jsonb)
returns void
language plpgsql
set search_path = ''
as $$
begin
  if not public.is_master(target_game) then
    raise exception 'forbidden' using errcode = 'insufficient_privilege';
  end if;

  delete from public.depot_sections where game_id = target_game;

  insert into public.depot_sections (game_id, id, name, icon, owner_id, position, author_id, deleted_at)
  select target_game, s.id, s.name, s.icon, s.owner_id, s.position, s.author_id, s.deleted_at
  from jsonb_to_recordset(sections) as s (
    id text, name text, icon text, owner_id text, position integer, author_id text,
    deleted_at timestamptz
  );

  insert into public.depot_items (
    game_id, id, section_id, owner_id, name, kind, quantity, notes, position,
    author_id, edited_by, created_at, updated_at, deleted_at
  )
  select target_game, i.id, i.section_id, i.owner_id, i.name, i.kind, i.quantity, i.notes,
         i.position, i.author_id, i.edited_by, i.created_at, i.updated_at, i.deleted_at
  from jsonb_to_recordset(items) as i (
    id text, section_id text, owner_id text, name text, kind text, quantity integer, notes text,
    position integer, author_id text, edited_by text, created_at timestamptz,
    updated_at timestamptz, deleted_at timestamptz
  );
end;
$$;

revoke execute on function public.replace_depot(uuid, jsonb, jsonb) from public, anon;
grant execute on function public.replace_depot(uuid, jsonb, jsonb) to authenticated;

-- ---------------------------------------------------------------- realtime

-- Inserts and updates respect the RLS above. Deletes only carry the primary
-- key (default replica identity), so nothing of a private item leaks.
alter publication supabase_realtime add table public.depot_sections, public.depot_items;
